from collections import Counter, deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1) if y in (r0,r1) or x in (c0,c1)}
            if all(grid[y][x] == color for y,x in perimeter):
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        out[y][x] = 7 if (r1 - r0 - 1) % 2 else 2
    return out

